-- The wilder Dithers: the heronry, the Holt beyond it, the turf diggings, and the Keeping.

space {
  id = "di_heronry",
  region = "dithers",
  name = "The Heronry",
  description = "The lode runs in under a wood of alder and crack willow standing in the water, and the light goes green, and then you smell it. Overhead, in every fork, there is a platform of sticks the size of a cartwheel, and on every platform a tall grey bird standing on one leg. There are sixty nests. The leaves below them are whitewashed. The noise is of a council of elderly lawyers being strangled, slowly, and enjoying it.",
  palette = { bg = "#0a0f0c", text = "#c8ccc0", dim = "#626a5c", accent = "#b0c4c8", border = "#34423c" },
  ambience = {
    fog { color = "#16201c", speed = 0.1, strength = 0.3 },
    drip { glyphs = "·˙", color = "#8a988c", rate = 0.35 },
    dust { glyphs = "·˙", color = "#56645a", rate = 0.3, speed = 0.4 },
  },

  things = {
    { name = "the herons",
      description = "Grey, white and black, four feet tall, with a neck like a question and a beak like the answer. On the nest they are solemn and upright and have a plume at the back of the head like a pen behind the ear. Then one of them opens its beak and all the dignity goes out of it at once.",
      things = {
        { name = "a heron arriving", description = "It comes in over the trees with its neck folded and its legs trailing, enormous, slow, and lands on a twig that should not hold a wren. It sways. It gets its balance. It looks round to see who saw." },
        { name = "a heron doing nothing", description = "One leg, eyes half shut, in the top of a willow. It has done nothing since you came and will do nothing after you leave. There is a view in the Dithers that the herons are the only ones who have understood the place." },
        { name = "two herons greeting", description = "One comes back to the nest. The other stands up, stretches its neck straight at the sky, and they clatter their beaks together like two men fencing with umbrellas. They do this every time. It has been forty minutes since they last met." },
      },
      actions = {
        { "Stand underneath", say "You look up. A heron looks down. There is a moment of mutual consideration. Seth Quant moves the punt one yard to the left, without comment, and something large and white lands where you were." },
      } },
    { name = "the nests",
      description = "Great flat rafts of stick, added to every year. The oldest are six feet deep and have small trees growing out of the sides. Sparrows nest in the basements.",
      things = {
        { name = "the young", description = "Three to a nest, all beak and grey fluff and outrage, with crests that stand straight up. They are fed by a parent being sick into them. They complain about the service throughout." },
        { name = "the lowest nest", description = "Built in the first fork of a leaning willow, a yard above the water. The pair that own it are young and did not know. The others look down on them, in both senses. They have raised more chicks than any nest in the wood." },
        { name = "a fallen nest", description = "Half in the water, as big as a bed. A coot has moved into the ruin and is extremely grand about it." },
      } },
    { name = "the heron-ward",
      icon = "☺",
      description = "An old man in a flat boat under the trees, with a hat like a roof, for the obvious reason. This is Gabriel Hernshaw. His family have kept the heronry for the Crown since some king liked heron pie. No king has asked for a heron in two hundred years. He goes on counting them.",
      things = {
        { name = "his hat", description = "Tarred canvas, two feet across, with a gutter round the brim and a spout at the back. It was white once. That is to say, it has been white many times." },
        { name = "his book", description = "{i}Herons, sitting: 60. Herons, standing: 114. Herons, deceased: 1 (age). Herons required by His Majesty: 0.{/} The last column goes back, in that one figure, through nine volumes." },
      },
      actions = {
        { "Ask what he does", say "\"Count 'em. Keep the boys off the eggs. Write to the King, first of the month, to say they're ready when he is.\" He scratches under the hat. \"Had a reply once. My grandfather did. It said, {i}Noted{/}.\" He says it with pride." },
        { "Ask about the Holt", say "He looks at the far side of the wood, where the trees are thickest. \"There's a house, back there. Three ladies. They've a lease off the herons, as I understand it.\" He lowers his voice. \"I'd take you, only you want the book. They can tell. I went once without the book and I couldn't find the door. Went round the house twice. It hasn't a great many sides.\"" },
      } },
    { name = "the whitewash",
      description = "Everything under the nests is white: leaves, branches, the water itself has a skin on it. It kills the lower boughs. A heronry eats its own wood from the top down, over a century, and then moves to the next. This one has moved four times. You can see where it was by where nothing grows.",
      things = {
        { name = "the nettles", description = "The one thing that thrives on it. They stand eight feet high on every hummock, dark and rank, and peacock butterflies sit on them in the sun, opening and shutting like small expensive books." },
      } },
    { name = "the fish that fall",
      description = "A young heron drops its dinner about one time in five. There is a steady light rain of roach and small eel under the trees. Things live on this. A pike lies in the shade doing no work at all, and an otter comes through at four each afternoon with the look of a man collecting rents.",
      actions = { { "Catch one", say "You hold out your hat. In due course a dace arrives in it from fifty feet up, alive and considerably surprised. You put it back in the water. It goes off at speed with a story nobody will believe." } } },
    { name = "the crack willows",
      description = "Old pollards, each one a fat trunk with a mop of rods on top. They split down the middle when they get too heavy and go on growing in both halves. A willow in the Dithers does not die. It just becomes more than one opinion.",
      things = {
        { name = "a hollow trunk", description = "With a little owl in it, the size of a fist, glaring. It lives directly under sixty herons and has the expression you would expect." },
        { name = "a willow growing from a willow", description = "A branch fell, floated, lodged in the fork of another tree and rooted there. It is now twenty feet tall, with its feet in a tree. Nobody told it." },
      } },
    { name = "the oldest heron",
      description = "On a dead bough over the lode, alone, almost white with age. One eye is clouded. The heron-ward calls him the Archdeacon. He no longer fishes. The others bring him things, and he accepts them as his due, and sometimes hands them back.",
      actions = { { "Bow to him", say "You bow from the punt. The Archdeacon lowers his head a quarter inch, then raises one foot from the bough, holds it a moment, and puts it down. Gabriel Hernshaw breathes out. \"He don't do that for the Reeve,\" he says." } } },
    { name = "a spoonbill",
      description = "One, white, among the grey, with a beak like a wooden spoon that it sweeps from side to side in the shallows. It arrived six years ago from nobody knows where and has behaved ever since as if it were a heron with a slight difficulty. The herons have decided not to mention it." },
    { name = "the green light",
      description = "Sun comes down through three storeys of leaf and lands on the water in coins. The lode is roofed. After the open fen and all that sky, it is like coming indoors, into a large untidy cathedral where the choir is having a dispute." },
    { name = "eggshells",
      description = "Floating among the roots: pale blue, the size of a hen's, broken neatly round the middle. Each one is the colour of a clear evening. The water under the heronry is scattered with small pieces of sky that something large has climbed out of and begun shouting." },
    { name = "the far side of the wood",
      key = "di_holt_side",
      description = "Where the alders stand closest, the lode ends in a wall of roots and bramble. There is no way through. The herons do not nest on that side. There is one thread of blue smoke going up beyond the trees, very straight.",
      variants = {
        { when = item "di_circle_book", description = "Where the alders stand closest, there is a gap you would have sworn was not there: a channel one punt wide, with the brambles tied back on either side with red thread. At the end of it, a landing, a path of cockle shells, and a chimney. The book is warm in your pocket." },
      } },
    { name = "a water rail",
      description = "A thin brown bird slipping between the roots like a pickpocket. It squeals like a pig. Nobody ever sees it do so. It is always looking at you blandly from a different place when the squeal stops." },
  },

  exits = {
    { to = "di_staithe", label = "By punt: the staithe", description = "Back down the heron's lode, with your hat held ready." },
    { to = "di_coven", label = "The gap in the alders",
      description = "Along the channel with the brambles tied back, to the landing and the shell path.",
      requires = item "di_circle_book", hidden = true },
  },
}

space {
  id = "di_coven",
  region = "dithers",
  secret = true,
  name = "The Holt",
  description = "A round house of wattle and thatch on an island of its own, with a herb garden, a goat, a beehive and a broom by the door. Inside there is one room, a fire in the middle, and three chairs drawn up to it. Three women are sitting in them with a book each. There is a cauldron on the fire. It has soup in it. This is the coven of the Dithers. It meets on Tuesdays, it has met on Tuesdays for nine hundred years, and for the last three hundred it has mostly been about the reading.",
  palette = { bg = "#100b10", text = "#d4c8d0", dim = "#74627a", accent = "#c890d8", border = "#48304e" },
  ambience = {
    flicker { color = "#e89858", strength = 0.2 },
    steam { glyphs = "˙·∙", color = "#6a5a6c", rate = 0.3 },
    embers { glyphs = "·˙", color = "#b070c0", rate = 0.06 },
  },

  things = {
    { name = "Mistress Mould",
      icon = "☻",
      description = "Agnes Mould, the eldest, straight as a poker in a black dress with a white collar. She has the book open on her knee and a pencil in her hand, and she is correcting it. She has been the senior witch of the Dithers for seventy years. She can sour milk at a mile, call a pike by name and stop a clock by looking at it, and she has not done any of these since she discovered the three-volume novel.",
      things = {
        { name = "her pencil", description = "Sharpened to a point you could sew with. In the margin of her copy: {i}No.{/} {i}No.{/} {i}Henbane is not gathered in March, sir.{/} {i}No.{/}" },
        { name = "her spectacles", description = "Two round lenses of smoked rock crystal. Through them she can see the truth of a person. She takes them off to read novels. She says it spoils the characters." },
      },
      actions = {
        { "Give an opinion of the book", set "di_opinion",
          say "You say you thought the horse was very well drawn. There is a silence. Mistress Mould removes her spectacles. \"That,\" she says, \"is Keziah Mallow's opinion. I have had it from her for six weeks, through the floor.\" She waits. You say, in your own voice, that you thought the Squire talked too much and the fen in the book was not wet enough. Three heads turn. \"Not wet enough,\" says Mistress Mould, slowly, and writes it down. A chair you had not seen is found to be behind you." },
        { "Ask if she still does magic", say "\"Magic.\" She closes the book on her finger. \"Young person, I turned the tide at Saltwick when I was nineteen, for a wager. It gave me no satisfaction. It simply went out. There was no second volume.\" She opens the book again. \"I will tell you what is harder than turning a tide. Getting three women to finish the same book by the same Tuesday.\"" },
      } },
    { name = "Dorcas Withy",
      icon = "☻",
      description = "The basket maker, in her other chair. Without the hive between her knees she looks no different, only more so. She is the middle witch. Her craft is binding: she can weave a thing so it holds what it was not made to hold. Tonight she is binding a split in the book's spine with waxed thread, since somebody has been reading it in the bath.",
      actions = {
        { "Ask what she binds", say "\"Baskets. Banks, when they slip. A promise, twice, for people who wanted it to hold.\" She pulls the thread tight. \"Slodge's causeway. He thinks it's the faggots. I let him.\" She bites the thread. \"The inn, to the fen, on a long line. Did you think it came back every night by luck?\"" },
      } },
    { name = "Miss Fogg",
      icon = "☻",
      description = "Petronella Fogg, the youngest, who is perhaps sixty. She is small and pink and sits on the edge of her chair with both hands round a cup. She is the one who has actually read the book, twice, and cried at the horse. Her craft is weather. The fog on the mere is hers. She made it by accident as a girl and has never known how to take it back.",
      things = {
        { name = "her cup", description = "Camomile. There is a very small cloud standing over it, a hand high, raining back into the cup. She does not seem to know. It follows the cup when she puts it down." },
        { name = "her copy", description = "Soft as cloth, with wild flowers pressed at the sad parts. There are a great many wild flowers." },
      },
      actions = {
        { "Ask about the fog", say "She goes pinker. \"I was seven. I only wanted to hide. I'd broken a jug.\" She looks into her cup. \"So I wished there was somewhere nobody could see me, and there was, and it was a mile across. And nobody was cross about the jug, they were all so busy being lost.\" She sniffs. \"People have got fond of it now. Agnes says it would be rude to take it away.\"" },
        { "Ask what they will read next", say "\"Volume three!\" says Miss Fogg. \"If it comes,\" says Dorcas Withy. \"It will not improve,\" says Mistress Mould. They look at the fire. \"There was a time,\" says Mistress Mould, \"when we would have known how it ended by looking in the cauldron.\" \"We did look,\" says Miss Fogg. \"It was soup,\" says Dorcas Withy." },
      } },
    { name = "the cauldron",
      description = "Iron, three-legged, black, as wide as a cartwheel. It was cast before there was a King and has seen things in its time that would turn the stomach. For three hundred years it has seen leek and potato, and it is not complaining.",
      things = {
        { name = "the soup", description = "Leek, potato, a ham bone and something green from the garden. It is the best soup you have ever smelled. That may be the one piece of the old craft they kept up." },
        { name = "the rim", description = "Cast with a ring of running figures, worn nearly flat by nine hundred years of ladles. You make out a hare, a hound, and a woman with a broom, going round for ever, none of them gaining." },
        { name = "the hook", description = "It hangs from a chain that goes up into the dark of the roof and is not, as far as you can see, fixed to anything. You do not mention it. It seems the sort of thing a guest lets pass." },
      },
      actions = { { "Accept a bowl", say "Miss Fogg ladles it out. It is hot right through and tastes of every good kitchen you have been in. Half way down the bowl you find that you are no longer damp, anywhere, for the first time since the reed beds. Dorcas Withy catches your eye and looks at the ceiling." } } },
    { name = "the broom by the door",
      key = "di_broom",
      wonder = true,
      description = "A birch besom on an ash handle, bound with eelskin, leaning in the corner like any broom. It is worn down on one side to a slant. The floor round it is damp, in a ring, and the damp is salt. {magic}This is the broom that swept the sea out of the Dithers.{/} It was a bay once, from the wood to the horizon. One woman did it in one night, and stopped at dawn. The sea has been leaning on the far edge of the fen ever since, and it is this, in this corner, that it is afraid of.",
      variants = {
        { when = item "di_sea_broom", name = "the corner by the door", description = "A damp ring on the floor, white at the edge with salt, where the broom leaned for nine hundred years. A newer broom has been stood in it, so the place should not feel the lack. The newer one is from the general shop in Greenhollow, and it is trying." },
      },
      actions = {
        { "Ask about the broom", when = no(flag "di_opinion"), say "\"That is not for discussion with persons who have not done the reading,\" says Mistress Mould, without looking up." },
        { "Ask about the broom", when = all(flag "di_opinion", no(item "di_sea_broom")), give "di_sea_broom",
          say "\"Mother Dredge's,\" says Dorcas Withy. \"She was the first of us. Swept the sea back to grow leeks.\" \"She stopped at dawn because her back hurt,\" says Miss Fogg. \"She stopped,\" says Mistress Mould, \"because she saw that if she finished, it would be a field, and anybody can have a field.\" They look at it. \"It wants an outing,\" says Dorcas. \"It has stood in that corner for nine centuries listening to us discuss novels.\" Mistress Mould puts it in your hands herself. \"You will not use it,\" she says. It is not a request. \"The sea knows where it is. That has always been sufficient.\"" },
      } },
    { name = "the bookshelves",
      description = "They go round the whole wall, floor to thatch, bent to the curve of the house. Three hundred years of Tuesdays. Every book the Circle has read is here in three copies, each with its own margins.",
      things = {
        { name = "a shelf of grimoires", description = "At the bottom, behind the log basket. Black, clasped, chained. They have not been opened in living memory. One of them is growling, quietly, like a dog that has been told to stay. Miss Fogg dusts them on Fridays and tells them what the others are reading." },
        { name = "the novels", description = "Row on row. {i}The Bride of the Lode. Lady Maud's Mistake. The Curate of Creeping Parva.{/} In each, one copy is annotated {i}No{/}, one is rebound, and one has flowers in it." },
        { name = "the minute book", description = "{i}Tuesday. Present: A.M., D.W., P.F. The book was discussed. A.M. held that it was nonsense. P.F. wept. D.W. mended the spine. Soup. Any other business: none. The sea: still out.{/} Every entry, for three hundred years, ends with those last three words." },
        { name = "a gap on the shelf", description = "The width of one volume. A card: {i}The Squire of Soggy Hall, vol. 2. Lent to K. Mallow. She has been written to.{/} Three times, by the look of the pencil." },
      },
      actions = { { "Take one down", say "You open {i}The Curate of Creeping Parva{/} at random. {i}No{/}, says the margin. You try the next copy. A pressed violet falls out, and Miss Fogg says \"Oh, that bit,\" from across the room, and has to be given a handkerchief." } } },
    { name = "the three chairs",
      description = "A tall hard one, a wide low one, and a small one with a cushion. They have been in those places so long that the floor has dipped under each. There is no dip for a fourth. The stool they found for you has been fetched from the goat.",
      things = {
        { name = "the tall chair", description = "Carved on the back with an eye. It is shut. Mistress Mould says it opens when a lie is told in the room, and that it has not opened since a visitor in her mother's time said he had enjoyed the book." },
      } },
    { name = "the cat",
      icon = "c",
      description = "Black, naturally, on the hearth, with her paws tucked in. She is called Mrs Henderson. She is nobody's familiar. She came in out of the rain eleven years ago and has views on the novels, which she expresses by where she sits. Tonight she is sitting on volume two.",
      actions = { { "Ask the cat's opinion", say "She looks at you, then at the book under her, then gets up, turns round, and sits on it facing the other way. \"There,\" says Mistress Mould. \"I said so. Even the cat.\"" } } },
    { name = "the herb garden",
      description = "Through the back door: nine beds in a ring, edged with cockle shells. Everything in it has two uses and Mistress Mould will only tell you the one.",
      things = {
        { name = "the henbane", description = "Grey, sticky, with flowers the colour of a bruise. For toothache, she says. You do not ask what the second use is. The plant looks as if it knows." },
        { name = "the leeks", description = "A double row, fat and blue-green, earthed up like soldiers. The best in the kingdom. They grow in ground that was sea bottom, on what the sea left. This is the whole of what Mother Dredge wanted, and she got it." },
        { name = "a mandrake", description = "In a pot of its own, with a small knitted cap on. It is Miss Fogg's. She could not bear to pull it. It is forty years old and has grown used to being read to." },
      } },
    { name = "the goat",
      description = "White, bearded, tethered by the door on a long rope, with yellow eyes and a slot for a pupil. A witch's goat is expected to be sinister. This one does its best. It has been found twice in the house eating volume one.",
      actions = { { "Meet its eye", say "It holds your gaze. There is something very old and knowing in it. Then it sneezes, looks startled, and eats a cockle shell." } } },
    { name = "the beehive",
      description = "A straw skep on a stool in the garden. The bees are told everything, as is proper: births, deaths, and how the book is going. When the Circle dislikes a novel, the honey is thin that month." },
    { name = "a row of pattens and three hats",
      description = "By the door. Three pairs of iron pattens and three tall black hats on pegs, steeple-crowned, in the old style. The hats have not been worn since the Reeve's grandfather said something. There is a wren's nest in the middle one. They are very careful, taking down the other two." },
    { name = "the window",
      description = "Small, round, with one bull's-eye pane. Through it you see the heronry, upside down and very small, and beyond it a fen that is not quite the one you came through. There is less water in it. There is a line of white at the far edge, like a thing kept waiting." },
  },

  exits = {
    { to = "di_heronry", label = "The shell path", description = "Out past the goat and back by the channel, with the brambles closing behind." },
  },
}

space {
  id = "di_peat",
  region = "dithers",
  name = "The Turbary",
  description = "The black lode ends at the diggings. Here the fen has been cut down in steps, like a quarry, into pits as big as fields with walls of wet black peat the height of two men. Stacks of turf stand drying on the tops in rows, like a town of small dark houses. Men are working along the face with long spades. Every spit they lift was laid down in a summer nobody remembers, and they are throwing a hundred years onto the barrow with each swing.",
  palette = { bg = "#0c0a08", text = "#ccc4b4", dim = "#6a6050", accent = "#c89858", border = "#40342a" },
  ambience = {
    fog { color = "#1a1612", speed = 0.1, strength = 0.3 },
    dust { glyphs = "·˙", color = "#5c5040", rate = 0.4, speed = 0.4 },
    drip { glyphs = "·", color = "#6a5a48", rate = 0.2 },
  },

  things = {
    { name = "the turf cutters",
      key = "di_turfs",
      icon = "☺",
      description = "Ezra Turf and his four sons, in a line along the face, black to the eyes. Each has a becket, a spade with a wing on it that cuts two sides at once. They cut in time. A brick comes off the face, turns in the air and lands on the barrow, every breath, from all five. None of them has ever been seen to look.",
      things = {
        { name = "Ezra Turf", description = "Seventy, bent, and stronger than any of the boys. He owns the cart on the causeway. He says the peat tells him where to cut. The boys say that is right, and it tells him through his knees, loudly, about four every morning." },
        { name = "a becket", description = "The blade is bright as a mirror from the cutting and the shaft is black from the hands. On the wing somebody has stamped a year. It is the year it was last reshod. The first year has worn off under it, and the one before that." },
        { name = "the youngest son", description = "Twelve, on the barrow, catching. He is not allowed a becket till he can catch a hundred bricks without dropping one. He is at ninety-one. The other four are cutting very slightly faster." },
      },
      actions = {
        { "Ask how deep it goes", say "\"Twenty foot here. Thirty by the mere.\" Ezra does not stop. \"Under that there's blue clay and under that I don't know, I've a living to get.\" A brick turns in the air. \"Every foot's a thousand year, the Survey man said. I said, then I've dug up more time than the King's got. He wrote it down.\"" },
        { "Ask what they will not cut", set "di_knows_keeping",
          say "The cutting stops, all five at once. It is the first quiet since you came. \"There's a piece west of here,\" says Ezra. \"Soft. Red moss on it. We call it the Keeping. You put a spade in there, it comes out clean. Not wet, not black. Clean.\" He looks at his sons. \"What goes in there stays as it went. My grandfather dropped his dinner in it. We saw it last spring. Bread's still warm.\" He spits. \"There's a board walk out to it, behind the last stack. I'd not take anything. I'd not leave anything either, without I wanted it back the same.\"" },
      } },
    { name = "the face",
      description = "A wall of peat, cut clean, shining wet. It is banded like bacon: black, brown, a streak of grey, black again. Each band is a kind of weather that went on for longer than the kingdom has had a name.",
      things = {
        { name = "the top band", description = "Brown, fibrous, full of reed root you can still pull out in strings. That is the Dithers as it is now, going down at a finger's width a year under its own weight." },
        { name = "a band of tree stumps", description = "Eight feet down the face, a row of them, cut through: oak and pine, standing where they grew, roots and all, black and sound. There was a forest here. Then there was a fen on top of it. The Mumblewood, you think, used to come a good deal further west, and something made it step back." },
        { name = "a grey streak", description = "A hand's width of fine silt with shells in it. Sea shells. Just the one layer, all the way along the face, level as a shelf. \"That's the night she swept,\" says the youngest boy, and is told to mind his barrow." },
        { name = "hazel nuts", description = "Thousands, in one seam, each with a neat hole where a mouse got in. They are ten thousand years old and you could plant what is left. Somewhere down the face there is the mouse." },
      },
      actions = { { "Put your hand on it", say "Cold, wet, and firm as cheese. It gives slightly. When you take your hand away the print fills with brown water, slowly, from the bottom. You have just touched a Tuesday from before there were any." } } },
    { name = "the Old Track",
      wonder = true,
      description = "At the foot of the deepest pit, under twenty feet of peat, the cutters have laid bare a road. It is made of oak trunks split in half and laid flat side up, pegged down with stakes, each plank a yard wide and smooth as a table. {magic}It runs dead straight across the floor of the pit and into the face on both sides.{/} Nothing else in the Dithers is straight. They have followed it for three generations, a pit at a time, and have not found either end.",
      things = {
        { name = "the planks", description = "Black, hard, with the marks of the tool still on them, crisp as the day. No rut. No hollow. No scrape of a hoof or a nail. {whisper}It was never walked on. Whoever laid it, laid it ready, before there was anyone to come along it.{/}" },
        { name = "the pegs", description = "Driven through square holes at every joint, oak into oak, each one trimmed off flush so that nothing should catch a foot. Somebody went down the whole length of it on their knees with a chisel, for the comfort of travellers. Ezra counted the pegs in one pit and gave up at four thousand." },
        { name = "where it goes into the face", description = "East, toward the wood, and west, toward the sea. They have cut along it far enough to know that it does not bend, and that it slopes, by a hair, always down to the west." },
        { name = "a thing set on the track", description = "In the middle of one plank, where they uncovered it: a round white pebble, placed, not dropped. They cut round it. It is still there, on a little pillar of peat, like something on a stand. Nobody has had the heart to move it." },
      },
      actions = {
        { "Walk a little way along it", say "You climb down into the pit and step onto the oak. It rings under your boot, sound as a floor. You take ten paces. They are the first ten paces anyone has ever taken on it, give or take the Turfs, who go round. You are glad, obscurely, to have been of use, and you step off with care, as from a clean doorstep." },
      } },
    { name = "the turf stacks",
      description = "Bricks stood on end in fives, then built into open walls so the wind goes through, then into beehive stacks with a thatch of sedge. It takes a summer to dry a brick. Wet, it weighs like a stone. Dry, it weighs like a loaf, and that is the fen's whole fuel, building stone and currency.",
      things = {
        { name = "a brick", description = "Dry, brown-black, a foot long. You can see the fibres in it: reed, moss, a leaf. You could light your pipe with a summer that an elk walked through." },
        { name = "the last stack", description = "At the western end, older than the rest, with moss on its thatch. Nobody takes from it. Behind it, a line of single planks sets off across the red moss, with a hazel wand stuck in beside each one." },
        { name = "a wheatear's nest", description = "In a gap between two bricks. The bird flicks in and out with a white rump like a dropped handkerchief. The Turfs stack round it. The stack will stand till she has done." },
      } },
    { name = "the bog oak",
      description = "A whole tree, dragged out of the face with chains and left on the top to dry: sixty feet of black trunk, no bark, hard as iron. It grew before the fen. A becket will not mark it.",
      things = {
        { name = "the grain", description = "Where a limb has been sawn off it is black right through, and it shines. A carver in Aldmoor pays for it by the ounce. He makes chess pieces. He has never needed to stain the black side." },
        { name = "a carving, started", description = "The second son's. He is making a heron out of a root, in the evenings. It has taken two years. The wood blunts a knife in a dozen strokes, and he says that suits him, since he was in no hurry and neither was it." },
      },
      actions = { { "Knock on it", say "It rings. Not like wood. Like a bell with a cloth over it. A long low note, and the cutters down in the pit look up, all five, as they would for a neighbour." } } },
    { name = "the drainage mill",
      description = "A small tarred windmill on the edge of the pit, with four canvas sails, turning a wooden wheel that scoops water up out of the diggings and tips it in the lode. If it stopped, the pit would be a pond by Sunday. It turns on days with no wind, at the same pace as the mill in Greenhollow, and for all anyone knows for the same reason.",
      things = {
        { name = "the scoop wheel", description = "Twelve paddles, lifting a bucketful each a yard and a half. It has been lifting the same water for a hundred years. The water goes down the lode, round by the staithe, soaks back through the peat and is waiting in the pit by morning." },
      } },
    { name = "the barrows",
      description = "Flat, with no sides and one broad wheel like a drum, so as not to sink. They run on a road of planks from the face to the stacks. The planks are moved forward as the face goes back. In sixty years the road has travelled half a mile and never been longer than forty yards." },
    { name = "things from the peat",
      description = "On a shelf in the cutters' hut: what the becket has turned up. The peat keeps everything a little. Not like the Keeping. Just kindly, the way a drawer does.",
      things = {
        { name = "a leather shoe", description = "One piece, laced with a thong, small enough for a child. Tanned as dark as the peat. The stitch holes are all there. So is the wear at the heel, on the outside, where she turned her foot." },
        { name = "a wooden bowl of butter", description = "Bog butter: a tub of it, white and hard as wax, buried to keep cool by somebody who then did not come back for it for two thousand years. The youngest boy tried it for a dare. He says it is not bad. He says it tastes of patience." },
        { name = "a bronze spearhead", description = "Green, leaf-shaped, with a rivet hole. Thrown in, not lost. People used to give the fen their best things. Ezra says it is the only bank that never failed." },
        { name = "an antler", description = "As wide as your two arms, with a palm like a shovel. Elk. There are no elk. The peat has not been told." },
      } },
    { name = "the pit pools",
      description = "The old workings have filled, and each is a square black pond with straight sides, full of water like strong tea. Dragonflies own them. In the oldest, white water crowfoot has spread from corner to corner, so that a pit dug for fuel has turned by itself into a lawn of flowers.",
      things = {
        { name = "a raft spider", description = "On the surface at the edge, brown with two cream stripes, as big as your palm, with its front feet resting on the water to feel for ripples. It is fishing. It has never heard that spiders do not." },
      } },
    { name = "the cutters' hut",
      description = "Built of turf, roofed with turf, heated with turf. Five hooks, five mugs, one bench. It is the same colour as the ground and you did not see it till a door opened in the bank.",
      actions = { { "Look in", say "Dark, warm and dry as a nut. There is a kettle on a turf fire in a turf hearth. On the wall, in chalk, a tally of bricks in bundles of five, running into the tens of thousands, and in a corner, smaller: {i}91{/}, crossed out, and {i}0{/}. The boy has dropped one." } } },
    { name = "cotton grass",
      description = "On the uncut bog, as far as you can see: white tufts on thin stems, all streaming one way in the wind. From the pit bottom, looking up, the edge of the fen is fringed with it against the sky, like the hem of something enormous that has been left to dry." },
    { name = "a curlew",
      description = "Somewhere over the moss, calling: a long bubbling rise that seems to come out of the ground itself. The cutters stop for it, for one breath, every time. It is the only thing they stop for besides the question you asked." },
  },

  exits = {
    { to = "di_staithe", label = "By punt: the staithe", description = "Back up the black lode, over its paving of dropped bricks." },
    { to = "di_keeping", label = "The planks behind the last stack",
      description = "Out over the red moss, a board at a time, by the hazel wands.",
      requires = flag "di_knows_keeping", hidden = true },
  },
}

space {
  id = "di_keeping",
  region = "dithers",
  secret = true,
  wonder = true,
  name = "The Keeping",
  description = "A hollow in the bog, half a mile across, carpeted in moss the colour of raspberries and wine. There is no open water. The surface gives under the planks like a bed. It is very quiet, and there is no smell at all. Things are lying on the moss, or just under it, as far as you can see: a basket, a ladder, a cart with its horse. {magic}Whatever the Keeping takes, it keeps exactly as it was at that moment, and neither one thing more nor one thing less.{/} You look at your own boot print on the last plank. It has not begun to fill.",
  palette = { bg = "#100809", text = "#d8c8c4", dim = "#7a5e5c", accent = "#e07088", border = "#4c2a30" },
  ambience = {
    shimmer { color = "#5a2a34", strength = 0.15 },
    dust { glyphs = "·", color = "#6a4a4c", rate = 0.1, speed = 0.1 },
  },

  things = {
    { name = "the red moss",
      description = "Sphagnum, deep as a mattress, in every red there is. You press a hand into it. It is neither warm nor cold. It is the same as your hand. When you lift it away the hollow stays, each finger clear, and you understand that it will stay.",
      things = {
        { name = "a handprint", description = "Beside yours, a hand's width off: another. Smaller, with a ring on the third finger. It is as sharp as the one you just made. Ezra's grandmother, they say, the day she was married." },
        { name = "a dewdrop", description = "On a moss tip, round and whole, with the sky in it. The sky in it is clear and early. Overhead it is clouding for rain. The drop has kept its own morning." },
        { name = "sundews", description = "Red stars on the moss, each leaf beaded with glue, each with a gnat. The gnats are whole and their wings are spread. Not one has been eaten. The sundews have been about to dine since before the King's grandfather." },
      } },
    { name = "the dinner",
      description = "A cloth spread on the moss, a little sunk. On it: half a loaf, a wedge of cheese with a bite out, an onion and a stone bottle on its side with the ale still running from the neck. The ale has been running from the neck for sixty years. It has not reached the cloth.",
      things = {
        { name = "the loaf", description = "You hold your hand over it. Warm. The crust is still crackling, faintly, the way bread does in the first minute out of the oven." },
        { name = "the bite in the cheese", description = "Tooth marks, clear as print, with one gap in the top row. Ezra Turf has that gap. So, they say, did his grandfather. So, in the pit, does the boy on the barrow." },
      },
      actions = { { "Smell the bread", say "It is the smell of a kitchen sixty years gone, with the fire lit and somebody singing. You stay bent over it longer than you meant to. Then you straighten up, and you leave it. It was not put down for you." } } },
    { name = "the horse and cart",
      description = "A hundred yards out, where no plank goes: a bay horse in the shafts of a hay wain, up to the hocks in moss. One forefoot is lifted. Its mane is blown to one side by a wind that dropped a very long time ago. On the box a man is leaning forward with the reins in his hand and his mouth open, about to say {i}whoa{/}.",
      things = {
        { name = "the carter", description = "Whiskers, a smock, a straw hat tilted back. He is not dead. Nobody who has seen him thinks so. He is in the middle of a word. The cutters take their caps off when they pass, not as you do for a grave. As you do for a man who is busy." },
        { name = "the hay", description = "Still green. A corner of the load has slipped and is hanging in the air, a forkful, a hand above the moss. There is a butterfly on it." },
        { name = "the horse's eye", description = "Brown, wide, catching a light that is not today's. It is looking at where it was going. You have the feeling that it knows perfectly well what has happened and has decided to be patient about it, as horses are about most things men get them into." },
      },
      actions = { { "Call to him", say "Your voice goes out across the moss and is not answered and does not echo. Nothing stirs. But the forkful of hay, you would swear, is lower by the width of a straw than when you first looked. He will get his word out. It is only that it is taking the fen a long time to hear it." } } },
    { name = "the King in the Peat",
      key = "di_peat_king",
      icon = "♔",
      description = "At the end of the plank walk, lying on the moss as on a bed, there is a man. He is tall and brown as a saddle, with a short red beard and a cloak of woven wool pinned at the shoulder. His hands are folded. His eyes are shut. He looks thirty and has looked thirty since before Aldmoor had a wall. Round his neck is a ring of twisted gold. He is the last of the Fen Kings. He lay down here on purpose.",
      variants = {
        { when = item "di_fen_torc", description = "The King in the Peat lies as he lay, with his hands folded and his eyes shut. His neck is bare now, and there is a pale line on it where the ring was. He looks more comfortable. One corner of his mouth, you would say, is higher than it was." },
      },
      things = {
        { name = "his face", description = "Every hair of the beard is there. There is a crease between the brows, and a small scar on the chin, and the look of a man who has made up his mind about something after a great deal of dithering." },
        { name = "his cloak", description = "Checked, red and a blue gone to grey, with a fringe. A bee is caught in the fringe. It is the oldest bee in the world and its wings are still a blur." },
        { name = "a staff beside him", description = "Alder, peeled, with a fork at the top. Leaves are opening on it. They have been opening since he laid it down." },
      },
      actions = {
        { "Speak to him", say "You say good day, feeling foolish. \"Is it,\" says the King in the Peat. His lips have hardly moved and his eyes have not opened. The voice is quiet and in no hurry. \"I had it as autumn. But I have not been keeping up.\" A pause the length of a breath, or a reign. \"You are standing in my light. No. Stay. It is company.\"" },
        { "Ask why he lay down", say "\"My fen was going under. A handspan a year. My people said, do something, you are the King. So I thought, what does a King do?\" The beard does not move. \"He keeps. So I came where the keeping is done, and lay down, and said: keep it as it is. Half land, half water. No worse.\" Something like a sigh. \"It has held, I think? Half and half? Good. Then I am still at work.\"" },
        { "Ask about the ring", when = no(item "di_fen_torc"), give "di_fen_torc",
          say "\"The torc. Yes. It is heavy.\" For the first time something moves: one brown hand unfolds, goes to his throat, and draws the gold off over the beard, slowly, like a man loosening his collar after a long dinner. He holds it out. \"A King needs it to be seen to be King. I am not seen. I am only doing the work.\" The hand opens. \"Take it somewhere dry. Do not put it on. It makes one responsible.\"" },
      } },
    { name = "the plank walk",
      description = "Single boards, end to end, each with a hazel wand beside it. The wands were cut green and pushed in a century ago. Every one has a single catkin on it, yellow, shedding a pinch of dust that hangs beside it in the air and does not fall.",
      actions = { { "Step off the plank", say "You put one foot on the moss. It takes it gently, to the ankle, and the cold stops and the damp stops and for a moment you cannot feel the foot at all, only that it is perfectly all right and will go on being so. You pull it out. It comes, slowly, with no sound. Your boot is clean. It has not been that clean since you bought it." } } },
    { name = "a ladder",
      description = "Lying flat on the moss with a pair of shears beside it. No tree within a mile. Somebody came out here to prune something, a very long time ago, and whatever it was has gone and left the errand." },
    { name = "a child's kite",
      description = "Paper, on a hazel cross, lying face up with its tail curled. The string runs off across the moss, taut, at an angle, up into the air and stops. Twenty feet of string, standing up from the ground with nothing on the end of it but the last pull of somebody's hand." },
    { name = "a hare",
      description = "In mid stride, a little way off, stretched out long with all four feet off the moss. It has a look of enormous purpose. Behind it, at exactly the distance it had gained, a fox is in the air too. Neither has caught or lost. Round them the Keeping has made the only fair race in the kingdom." },
    { name = "a row of things on a board",
      description = "Near the start of the planks, set out by the cutters' families on a length of bog oak. Not lost. Put. A wedding cake with one slice gone. A lit candle. A letter, sealed. A baby's first tooth in a thimble. A full glass.",
      things = {
        { name = "the lit candle", description = "Burning, upright, with a clear drop of wax half way down its side. The flame is steady as a painted one. It was lit by a woman who wanted one evening kept, and it has been that evening on this board ever since." },
        { name = "the sealed letter", description = "Addressed, in faded ink, {i}To be opened when I am sorry.{/} The seal is unbroken. The ink of the address is still wet." },
      },
      actions = { { "Consider leaving something", say "You go through what you have. A copper, an onion, the rest. You think about what it would be to have a thing kept exactly as it is, for good. You look at the carter with his mouth open. You put everything back in your pocket, where it can go on getting worn." } } },
    { name = "the edge",
      description = "Where the red moss meets the common bog there is a line you could draw with a stick. On one side cotton grass moves in the wind. On the other, a single tuft of it stands bent, in a gust it never got to the end of. A beetle is walking along the line, on the moving side, keeping to it with great care." },
    { name = "the sound",
      description = "There is none. Then you notice your own breath, and your coat, and the blood in your ears, and that these are the only things for half a mile that are getting on with it. You are, at this moment, the entire passage of time in the Keeping. It is a responsibility. You breathe out, to keep things going." },
    { name = "a robin",
      description = "On the last hazel wand, fully alive, with its head on one side. Birds will come to the edge and no further. It sings a few notes at the King, as it would at a man digging, on the chance that he will turn something up. Then it flies off east, where things happen." },
  },

  exits = {
    { to = "di_peat", label = "Back along the planks", description = "By the hazel wands to the last stack, where a kettle is boiling and will, in a minute, have boiled." },
  },
}
